export default {
  data() {
    return { count: 0 };
  },
  template: `
    <div style="font-family:sans-serif;">
      <p>Contador: {{ count }}</p>
      <button @click="count--">-</button>
      <button @click="count++">+</button>
    </div>
  `
};

const http = require('http');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(`
    <!doctype html>
    <html>
      <body style="font-family: sans-serif; padding: 24px;">
        <h1>🟢 Servidor Node.js rodando de verdade!</h1>
        <p>Rota acessada: <code>${req.url}</code></p>
        <p>Horário no servidor: ${new Date().toLocaleTimeString('pt-BR')}</p>
      </body>
    </html>
  `);
});

server.listen(3000, () => {
  console.log('Servidor no ar em http://localhost:3000');
});

// deps: express
const express = require('express');
const app = express();

app.get('/', (req, res) => {
  res.send(`
    <!doctype html>
    <html>
      <body style="font-family: sans-serif; padding: 24px;">
        <h1>🚀 Express rodando dentro do preview</h1>
        <p>Tente acessar <a href="/api/hora">/api/hora</a> pra ver uma resposta JSON de verdade.</p>
      </body>
    </html>
  `);
});

app.get('/api/hora', (req, res) => {
  res.json({ hora: new Date().toISOString() });
});

app.listen(3000, () => {
  console.log('Express no ar em http://localhost:3000');
});
